/** Restore rehearsal for synthetic data only. Does not read a production URL.
 * Uses the PostgreSQL service's own matching pg_dump/pg_restore binaries. */
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash, randomBytes, randomUUID } from "node:crypto";
import { mkdirSync, mkdtempSync, readFileSync, writeFileSync, copyFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import pg from "pg";
import { drizzle } from "drizzle-orm/node-postgres";
import { migrate } from "drizzle-orm/node-postgres/migrator";
const {url}=JSON.parse(readFileSync(".data/qa-database.json","utf8")), parsed=new URL(url);
if(parsed.hostname!=="127.0.0.1" || parsed.pathname!=="/maras_qa" || process.env.DATABASE_URL && process.env.DATABASE_URL!==url) throw new Error("Dedicated loopback QA connection required");
const container=process.env.QA_POSTGRES_CONTAINER;
if(container && !/^[a-f0-9]{12,64}$/.test(container))throw new Error("Invalid QA PostgreSQL container ID");
if(!container && process.env.QA_ALLOW_LOCAL_PG_TOOLS!=="true")throw new Error("Explicit local pg_dump/pg_restore consent or QA service container required");
const temporary=mkdtempSync(join(tmpdir(),"maras-restore-")), prefix="maras_qa_restore_"+randomBytes(6).toString("hex"), names=[prefix+"_source",prefix+"_old",prefix+"_new"], created=[],clients=[];
const parent=new pg.Client({connectionString:url,connectionTimeoutMillis:5000,statement_timeout:60000});await parent.connect();
const checks=[],pass=message=>{checks.push(message);console.log("PASS RESTORE",message);};
const q=value=>'"'+value.replaceAll('"','""')+'"';
function tool(command,database,input){
 assert.ok(names.includes(database)); assert.ok(["pg_dump","pg_restore"].includes(command));
 const args=["--username",decodeURIComponent(parsed.username),"--dbname",database,...(command==="pg_dump"?["--format=custom","--no-owner","--no-acl"]:["--no-owner","--no-acl","--exit-on-error","--single-transaction"])];
 const result=container?execFileSync("docker",["exec",...(input?["-i"]:[]),container,command,...args],{input,timeout:60000,maxBuffer:64*1024*1024,stdio:["pipe","pipe","pipe"]}):execFileSync(command,["--host",parsed.hostname,"--port",parsed.port||"5432",...args],{input,timeout:60000,maxBuffer:64*1024*1024,stdio:["pipe","pipe","pipe"],env:{...process.env,PGPASSWORD:decodeURIComponent(parsed.password)}});
 return result;
}
async function connect(name){const value=new URL(url);value.pathname="/"+name;const c=new pg.Client({connectionString:value.toString(),connectionTimeoutMillis:5000,statement_timeout:30000});await c.connect();clients.push(c);return c;}
async function snapshot(client){
 const tables=(await client.query("SELECT schemaname,tablename FROM pg_tables WHERE schemaname IN ('public','drizzle') ORDER BY schemaname,tablename")).rows;
 const result={};for(const t of tables){const key=`${t.schemaname}.${t.tablename}`;result[key]=(await client.query(`SELECT row_to_json(t)::text AS value FROM ${q(t.schemaname)}.${q(t.tablename)} t`)).rows.map(r=>r.value).sort();}
 const constraints=(await client.query("SELECT n.nspname,c.relname,con.conname,pg_get_constraintdef(con.oid) AS definition FROM pg_constraint con JOIN pg_class c ON c.oid=con.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','drizzle') ORDER BY 1,2,3")).rows;
 const columns=(await client.query("SELECT table_schema,table_name,column_name,data_type,is_nullable,column_default FROM information_schema.columns WHERE table_schema IN ('public','drizzle') ORDER BY table_schema,table_name,ordinal_position")).rows;
 const indexes=(await client.query("SELECT schemaname,tablename,indexname,indexdef FROM pg_indexes WHERE schemaname IN ('public','drizzle') ORDER BY 1,2,3")).rows;
 return {rows:result,constraints,columns,indexes};
}
try{
 for(const name of names){await parent.query(`CREATE DATABASE ${q(name)} TEMPLATE template0`);created.push(name);}
 const source=await connect(names[0]);const journal=JSON.parse(readFileSync("drizzle/meta/_journal.json","utf8")), legacyEntries=journal.entries.filter(entry=>entry.idx<=37);
 assert.equal(legacyEntries.at(-1).tag,"0037_stable_user_ownership");
 const folder=join(temporary,"legacy");mkdirSync(join(folder,"meta"),{recursive:true});writeFileSync(join(folder,"meta/_journal.json"),JSON.stringify({...journal,entries:legacyEntries}));
 for(const entry of legacyEntries)copyFileSync(`drizzle/${entry.tag}.sql`,join(folder,`${entry.tag}.sql`));
 await migrate(drizzle(source),{migrationsFolder:folder});
 const owner=(await source.query("INSERT INTO users(email,full_name) VALUES ('restore-owner@example.test','Synthetic restore owner') RETURNING id")).rows[0];
 await source.query("INSERT INTO favorites(user_id,user_email,course_slug) VALUES ($1,'historical@example.test','restore-course'),(NULL,'unresolved@example.test','restore-legacy')",[owner.id]);
 await source.query("INSERT INTO support_tickets(user_id,user_email,ticket_number,category,title,message) VALUES ($1,'historical@example.test','RESTORE-1','general','Synthetic','Preserve this historical record')",[owner.id]);
 const before=await snapshot(source), oldDump=tool("pg_dump",names[0]);writeFileSync(join(temporary,"before.dump"),oldDump,{mode:0o600});
 assert.ok(oldDump.length>0);pass("pre-migration snapshot and custom-format backup preserve stable owners and unresolved legacy records");
 await migrate(drizzle(source),{migrationsFolder:"./drizzle"});
 const upgraded=await snapshot(source);for(const [table,rows]of Object.entries(before.rows))if(table!=="drizzle.__drizzle_migrations")assert.deepEqual(upgraded.rows[table],rows,table);
 const task=randomUUID();await source.query("INSERT INTO storage_cleanup_jobs(id,kind,provider,object_key,source) VALUES ($1,'object','local','qa/restore-only','qa-restore')",[task]);
 pass("actual 0038 and 0039 migrations upgrade the legacy schema without rewriting existing account data");
 const after=await snapshot(source), newDump=tool("pg_dump",names[0]);writeFileSync(join(temporary,"after.dump"),newDump,{mode:0o600});
 tool("pg_restore",names[2],newDump);const restored=await connect(names[2]);assert.deepEqual(await snapshot(restored),after);
 assert.equal((await restored.query("SELECT status FROM storage_cleanup_jobs WHERE id=$1",[task])).rows[0].status,"pending");
 pass("latest backup restores all table rows, columns, constraints, indexes and committed cleanup intent into a fresh database");
 await source.query("BEGIN");try{await source.query("ALTER TABLE users ADD COLUMN qa_failed_migration text");await source.query("INSERT INTO storage_cleanup_jobs(id,kind,provider,object_key,source) VALUES ($1,'object','local','qa/duplicate','qa-restore')",[task]);assert.fail("expected unique rejection");}catch(error){assert.equal(error.code,"23505");await source.query("ROLLBACK");}
 assert.deepEqual(await snapshot(source),after);pass("a failed transaction rolls back both schema and data changes without partial migration state");
 tool("pg_restore",names[1],oldDump);const rolledBack=await connect(names[1]);assert.deepEqual(await snapshot(rolledBack),before);
 assert.equal((await rolledBack.query("SELECT to_regclass('public.storage_cleanup_jobs') AS name")).rows[0].name,null);
 pass("restoring the pre-upgrade backup returns both application data and migration metadata to the exact old schema");
 const report={passed:checks.length,checks,serverVersion:(await source.query("SHOW server_version")).rows[0].server_version,backupSha256:{before:createHash("sha256").update(oldDump).digest("hex"),after:createHash("sha256").update(newDump).digest("hex")},scope:"synthetic PostgreSQL only; no production backup, no object-store backup, no PITR evidence",rollback:"restore into a separate database; requires quiescing writes and an approved recovery point in production"};
 mkdirSync(".data",{recursive:true});writeFileSync(".data/qa-backup-restore-report.json",JSON.stringify(report,null,2));
}finally{
 for(const c of clients)await c.end();for(const name of created.reverse())await parent.query(`DROP DATABASE ${q(name)}`);await parent.end();rmSync(temporary,{recursive:true,force:true});
}
